export const BODY: string = "\n<p>لقطات ماك وويندوز تُحفظ كـPNG افتراضيًا، وتلك الملفات ضخمة. لقطة واحدة قد تزن 2 ميغابايت.</p>\n<p>تحويل PNG إلى JPG هو أسرع طريقة لتصغير اللقطات والصور والرسوم التي لا تحتاج إلى شفافية.</p>\n<p>يشرح هذا الدليل كيف يعمل التحويل، ومتى تستخدمه، وكيف تتعامل مع مسألة الشفافية.</p>\n<h2 id=\"what-is-png-to-jpg\">ما تحويل PNG إلى JPG؟</h2>\n<p>ما تحويل PNG إلى JPG؟ إعادة ترميز صورة PNG بصيغة JPG مع ضغط مع فقدان. النتيجة ملف أصغر بكثير بالصورة نفسها تقريبًا.</p>\n<p>التحويل يزيل الشفافية لأن JPG لا يدعمها. البكسلات الشفافة تُملأ بلون تعبئة تختاره.</p>\n<h2 id=\"why-screenshots-are-huge\">لماذا لقطات PNG ضخمة جدًا؟</h2>\n<p>لماذا لقطات PNG ضخمة جدًا؟ لأن PNG ضغط دون فقدان يحفظ كل بكسل بدقة. لقطة شاشة فيها نصوص وألوان كثيرة تزن ميغابايتات.</p>\n<p>JPG يتجاهل التفاصيل الدقيقة التي لا تلاحظها العين، فيصغّر الملف إلى عُشر حجمه تقريبًا.</p>\n<h2 id=\"quality-settings\">إعدادات الجودة التي تعمل</h2>\n<p>إعدادات الجودة التي تعمل: جودة 85 مناسبة لمعظم اللقطات، و90 للقطات النصية التي تحتاج إلى حدة أكبر. جودة 95 للصور المهمة.</p>\n<p>لا تستخدم جودة أقل من 80 للقطات فيها نصوص. النص يضبب بسرعة عند الجودة المنخفضة.</p>\n<h2 id=\"matte-colour\">لون التعبئة: ملء الشفافية</h2>\n<p>لون التعبئة: ملء الشفافية. عندما تحوّل صورة شفافة إلى JPG، تُملأ المناطق الشفافة بلون تختاره، عادة أبيض.</p>\n<p>اختر لونًا يطابق خلفية الوجهة. أبيض لمعظم الحالات، وأسود للخلفيات الداكنة، ولون مخصص إذا لزم الأمر.</p>\n<h2 id=\"screenshots-and-text\">اللقطات وحدة النص</h2>\n<p>اللقطات وحدة النص: النص في اللقطات حساس للضغط. استخدم جودة 90 أو أعلى للحفاظ على النص حادًا وواضحًا.</p>\n<p>إذا ضبب النص بعد التحويل، فأعد التحويل بجودة أعلى. لا تحوّل من النسخة المحوّلة، بل من PNG الأصلي.</p>\n<h2 id=\"product-photos-and-logos\">صور المنتجات والقصاصات والشعارات</h2>\n<p>صور المنتجات والقصاصات والشعارات: صور المنتجات الفوتوغرافية تتحول إلى JPG بشكل ممتاز. الشعارات الشفافة تحتاج إلى عناية بلون التعبئة.</p>\n<p>إذا كان للشعار خلفية شفافة، فاختر لون تعبئة يطابق خلفية موقعك. اللون الخاطئ يجعل الشعار يبدو غريبًا.</p>\n<h2 id=\"batch-converting-screenshots\">كيف تحوّل اللقطات بالجملة؟</h2>\n<p>لتحويل اللقطات بالجملة، ارفع كل اللقطات وحوّلها بإعدادات موحدة. الأداة تحوّل الدفعة كاملة وتنزّلها كملف ZIP.</p>\n<p>راجع عينة من النتائج قبل الاعتماد على الدفعة كلها. إذا كان النص حادًا في العينة، فغالبًا بقية اللقطات بنفس الجودة.</p>\n<h2 id=\"file-size-savings\">كم حجمًا يمكنك توفيره؟</h2>\n<p>كم حجمًا يمكنك توفيره؟ التوفير كبير عادة: لقطة PNG بحجم 2 ميغابايت قد تصبح JPG بحجم 200 كيلوبايت بجودة 85.</p>\n<p>للصور الفوتوغرافية، التوفير أكبر. للرسوم البسيطة، التوفير أقل لأن PNG يضغطها جيدًا أصلًا.</p>\n<h2 id=\"png-vs-webp-decision\">PNG إلى JPG أم PNG إلى WebP؟</h2>\n<p>PNG إلى JPG أم PNG إلى WebP؟ اختر JPG للتوافق الكامل، وWebP لأصغر حجم على المواقع الحديثة. WebP أصغر من JPG بالجودة نفسها.</p>\n<p>إذا كانت الوجهة تدعم WebP، فهي الخيار الأفضل. وإذا لم تكن متأكدًا، فاختر JPG.</p>\n<h2 id=\"metadata-stripped\">البيانات الوصفية تُزال أثناء التحويل</h2>\n<p>البيانات الوصفية تُزال أثناء التحويل: بيانات EXIF مثل الموقع والتاريخ قد تُزال عند التحويل إلى JPG. هذا يحمي خصوصيتك عند المشاركة.</p>\n<p>إذا أردت الاحتفاظ ببيانات معينة، فتحقق من الملف المحوّل. بعض الأدوات تحافظ على البيانات، وبعضها يزيلها.</p>\n<h2 id=\"checking-quality\">كيف تراجع الجودة قبل التنزيل؟</h2>\n<p>كيف تراجع الجودة قبل التنزيل؟ قارن النتيجة بالأصل، وتأكد من أن النص حاد والألوان صحيحة ولا توجد تشوهات.</p>\n<p>كبّر الصورة وافحص التفاصيل الدقيقة. إذا بدت النتيجة جيدة مكبّرة، فهي جاهزة للاستخدام.</p>\n<h2 id=\"common-mistakes\">أخطاء شائعة يجب تجنبها</h2>\n<p>أخطاء شائعة يجب تجنبها: تحويل شعار شفاف بلون تعبئة خاطئ، واستخدام جودة منخفضة للنصوص، وتحويل كل PNG إلى JPG دون تمييز.</p>\n<p>تجنبها بمراجعة العينة أولًا، واختيار لون التعبئة بعناية، والاحتفاظ بـPNG للشعارات والرسوم الشفافة.</p>\n<h2 id=\"png-photos-from-phones\">صور PNG من الهواتف</h2>\n<p>صور PNG من الهواتف: بعض الهواتف تحفظ الصور كـPNG، وهي ضخمة. حوّلها إلى JPG للمشاركة والتخزين.</p>\n<p>للصور الفوتوغرافية من الهاتف، JPG هو الخيار الصحيح دائمًا. PNG يهدر المساحة دون أي فائدة.</p>\n<h2 id=\"screenshots-bug-reports\">لقطات لتقارير الأخطاء</h2>\n<p>لقطات لتقارير الأخطاء: حوّل اللقطات إلى JPG قبل إرسالها في تقرير خطأ. الملف الأصغر يرفع أسرع ويُقبل في معظم الأنظمة.</p>\n<p>استخدم جودة 90 للقطات التقارير. النص يجب أن يبقى مقروءًا، والجودة العالية تضمن ذلك.</p>\n<h2 id=\"sharing-screenshots-chats\">كيف تشارك اللقطات في المحادثات؟</h2>\n<p>لمشاركة اللقطات في المحادثات، حوّلها إلى JPG أولًا. الملف الأصغر يرسل أسرع ويستهلك بيانات أقل.</p>\n<p>للمحادثات اليومية، جودة 80 كافية. لا أحد يحتاج إلى لقطة بحجم 2 ميغابايت في محادثة.</p>\n<h2 id=\"converting-for-email\">كيف تحوّل الصور للبريد الإلكتروني؟</h2>\n<p>لتحويل الصور للبريد الإلكتروني، حوّلها إلى JPG لتقليل حجم المرفقات. البريد الإلكتروني له حدود حجم، وJPG يساعدك على البقاء ضمنها.</p>\n<p>إذا كان المرفق ما زال كبيرًا، فاضغط JPG أكثر أو قسّم الصور على عدة رسائل.</p>\n<h2 id=\"archiving-converted-jpgs\">كيف تؤرشف ملفات JPG المحوّلة؟</h2>\n<p>لأرشفة ملفات JPG المحوّلة، احتفظ بالأصول PNG في مجلد منفصل. الأصل هو مصدر كل نسخة مستقبلية.</p>\n<p>وللخطوات العملية، استخدم <a href=\"/ar/tahwil-png-ila-jpg/\">محول PNG إلى JPG</a>، واقرأ <a href=\"/ar/blog/kayfiyya-tahwil-png-ila-jpg/\">كيفية تحويل PNG إلى JPG</a> و<a href=\"/ar/blog/png-ila-jpg-hajm-al-malaf-wa-al-jawda/\">PNG إلى JPG: حجم الملف والجودة</a>، أو حوّل إلى WebP باستخدام <a href=\"/ar/tahwil-png-ila-webp/\">محول PNG إلى WebP</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"كم سيصغر ملف PNG كـJPG؟","answer":"تعتمد على الصورة، لكن التوفير كبير عادة: لقطة PNG بحجم 2 ميغابايت قد تصبح JPG بحجم 200 كيلوبايت بجودة 85."},{"question":"هل تحويل PNG إلى JPG يضبب نص لقطتي؟","answer":"قد يضبب النص قليلًا عند جودة منخفضة. استخدم جودة 90 أو أعلى للقطات النصية، وسيبقى النص حادًا وواضحًا."},{"question":"ما لون التعبئة الذي أستخدمه لشعار شفاف؟","answer":"اختر لونًا يطابق خلفية الوجهة: أبيض لمعظم الحالات، وأسود للخلفيات الداكنة. اللون الخاطئ يجعل الشعار يبدو غريبًا."},{"question":"هل يمكنني تحويل PNG إلى JPG على هاتفي؟","answer":"نعم، يعمل التحويل في متصفح هاتفك دون تثبيت أي تطبيق. افتح الأداة وارفع الصورة وحوّلها ونزّل النتيجة."},{"question":"هل يعمل تحويل PNG إلى JPG للمستندات الممسوحة؟","answer":"نعم، التحويل مناسب للمستندات الممسوحة. JPG أصغر بكثير، والنص يبقى مقروءًا عند جودة 85 أو أعلى."},{"question":"هل أحوّل كل ملفات PNG إلى JPG لتوفير المساحة؟","answer":"لا، لا تحوّل كل ملفات PNG إلى JPG. احتفظ بـPNG للشعارات والرسوم الشفافة، وحوّل فقط الصور الفوتوغرافية واللقطات."}];
